UPDATE courses SET subtitle=$q$Know What to Change in Your Directory Profile.$q$, description=$q$A personalized video audit of your Psychology Today, TherapyDen, or other directory profile, with specific feedback you can use to update it. Choose one, two, or three profiles.$q$, features=$q$["Clear, personalized feedback so you will know exactly what’s holding your profile back.", "An improvement plan so you will make changes with confidence.", "SEO and visibility insights for your profile.", "Actionable steps so you can make changes without rewriting everything."]$q$::jsonb, updated_at=now()
