UPDATE courses SET subtitle=$q$Stop Rebuilding Your Credentialing Process Every Time You Hire$q$, description=$q$A step-by-step credentialing system for group practice owners, designed to be repeatable, not owner-dependent. Insurance companies make their own credentialing and network participation decisions.$q$, features=$q$["A streamlined credentialing workflow so you will stop scrambling and start credentialing clinicians efficiently.", "Organized documentation systems so you will always know where things stand and avoid costly errors.", "A repeatable workflow for future hires, so you can train an administrative team member to manage it."]$q$::jsonb, updated_at=now()
